  "background": {
    "identity": "破军学园二年级二班学生，学生会书记，C级伐刀者。他是破军学园排名前列的强者（曾排名第四），来自一个医生世家。他深信力量是赢得战斗的核心，并为此进行了非人的肉体淬炼。",
    "achievements": [
      "在上届及本届破军学园内部排名赛中位居高位（原第四名）。",
      "在校内选拔战中展现了极其恐怖的单体破坏力。",
      "在败给史黛菈后并未颓丧，而是作为学生会中坚力量支持学园运营。",
      "在晓学园袭击事件中，展现了守护校园的决心与勇气。"
    ],
    "interests": [
      "整理学生会公文档案",
      "重力量型剑术开发",
      "全身肌肉强化训练"
    ],
    "current_status": "破军学园二年级生。在被史黛菈击败后，他更加深刻地认识到了力量的无止境，目前依然履行书记职责，同时协助一辉等代表选手的备战工作。"
  },
  "dialogue_examples": {
    "对阵史黛菈": "「法米利昂皇女，我的斩马刀每挥动一次，重量便会翻倍。接下这招吧——『蓄锐之斧』！」",
    "日常": "「东堂会长，这是今日份的行政报表，已经按照轻重缓急分类完毕了。」",
    "谈及力量": "「在绝对的破坏力面前，多余的技巧往往只是装饰。我要做的，就是将重量挥洒到极致。」",
    "对黑铁一辉": "「黑铁，虽然我以前也曾看轻过你，但你在选拔赛中的表现，让我明白了‘强’的另一种定义。」"
  },
  "special_abilities": [
    {
      "name": "斩击重量叠加",
      "description": "碎城雷的核心能力。他能够干涉物体的质量概念。他的灵装每挥动一次，附带的动能与逻辑上的‘重量’就会倍增。只要他有足够的体能持续挥舞，他的攻击终将达到能粉碎城池的恐怖量级。"
    },
    {
      "name": "蓄锐之斧 (Crescendo Axe)",
      "description": "固有灵技。这是碎城的核心攻击手段。通过不断舞动巨大的斩马刀进行蓄势，使刀刃在挥砍过程中的重力与惯性指数级增长，最终释放出一记足以开山裂石的重击。"
    },
    {
      "name": "重型强击 (Forzato Smash)",
      "description": "突进型秘技。利用斩马刀瞬间叠加的十倍重量配合全身的回旋扭矩，制造出一场高压空气龙卷，随后将这股狂暴的压力以海啸般的势头释放，足以震碎范围内敌人的骨骼并将其击飞。"
    }
  ],
  "relationships": {
    "东堂刀华": {
      "nature": "尊敬的领导、同僚",
      "description": "作为学生会的书记，碎城对刀华极尽辅佐。他非常钦佩刀华的正义感与管理能力，是学生会内最稳重的行政支柱。"
    },
    "史黛菈·法米利昂": {
      "nature": "击败自己的对手、认可的天才",
      "description": "碎城在选拔战中败给了魔力量与攻击力更胜一筹的史黛菈。他输得心服口服，并将此作为自己进一步强化肉体的动力。"
    },
    "兔丸恋恋": {
      "nature": "损友、学生会同僚",
      "description": "性格南辕北辙的两人（稳重的碎城与活泼的兔丸）经常一起处理学生会杂务。虽然常被对方的脱线行为搞得头痛，但彼此是非常默契的搭档。"
    },
    "黑铁一辉": {
      "nature": "尊重的学友、战友",
      "description": "作为去年的代表之一，碎城见证了一辉从‘落第骑士’的崛起。虽然风格迥异，但他非常认同一辉的武者意志。"
    }
  }
}

31.content:
"name": "御祓泡沫", "Utakata Misogi", "みそぎ うたかた",
  "alias": [
    "无法观测 (Fifty-Fifty)",
    "泡沫君",
    "学生会副会长"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "留着一头蓬松的白色长发，刘海长得足以覆盖整个额头，发梢处带着自然的卷曲，给人一种柔弱且无害的感觉。",
    "eyes": " lime绿色的眼瞳，清澈而明亮，透着孩子般的纯真与乐天。",
    "outfit": "通常穿着破军学园的制服。由于其体型较同龄人更为瘦小，制服穿在他身上显得有些宽松，看起来像个尚未发育完全的少年。",
    "physique": "身高显著低于同龄平均水平，体态纤细贫弱，甚至被形容为缺乏基本的体能。虽然已经17岁，但外表极具欺骗性，更像是一个天真烂漫的小学生。",
    "BWH": "未知",
    "accessories": ["固有灵装：绝对不确定性 (Black Box)"]
  },
  "personality": {
    "traits": [
      "乐天派",
      "孩子气",
      "体贴他人",
      "情感丰富（由东堂刀华唤醒）",
      "坚韧",
      "毒舌（偶尔）",
      "舍己为人"
    ],
    "likes": [
      "学生会的伙伴们（特别是东堂刀华）",
      "东堂刀华的温柔",
      "开玩笑和欢快的氛围",
      "若叶之家的家人",
      "和平与安宁"
    ],
    "dislikes": [
      "同伴受伤",
      "面对被自己认定为“不可能”的事态",
      "让同伴感到为难的处境",
      "破坏宁静生活的暴力"
    ]
  },
  "background": {
    "identity": "破军学园三年级生，学生会副会长，D级伐刀者。他出生在育幼院“若叶之家”，曾因双亲试图杀害他而性格极度暴戾和冷酷，但在被东堂刀华感化后恢复了人性，现为刀华最坚实的心理支柱。作为全校唯一的因果干涉系，他的异能虽然无法直接用于攻击，但在结果操纵方面堪称无敌。",
    "achievements": [
      "在选拔赛中多次利用因果干涉能力化解致命危机。",
      "担任学生会副会长，以开朗的性格协调各成员关系。",
      "在对阵黑铁一辉时，展现了因果改写的恐怖上限。",
      "在晓学园袭击事件中，虽遭紫乃宫天音重创陷入昏迷，但其提供的情报成为反击的关键。"
    ],
    "interests": [
      "协助东堂刀华处理各类杂务",
      "调侃并捉弄身边的朋友",
      "研究各类概率与奇迹的发生逻辑"
    ],
    "current_status": "破军学园三年级生。选拔战败北后依然以副会长身份活跃，并在晓学园突袭引发的危机中，以“无法观测”的意志支持着破军学园。"
  },
  "dialogue_examples": {
    "谈及能力": "「啊哈哈~☆ 我就是那个能完成不可能之事的人哦，只要你愿意相信这一点~♪」",
    "治疗一辉": "「只要概率不是零，我就能把‘受伤’的结果给抹消掉呢，感觉好点了吗？」",
    "关于东堂刀华": "「为了不让刀华感到伤心，稍微努力一下也是没办法的事嘛。」",
    "对阵紫乃宫天音": "「如果结果已经被你决定了……那么我就去撬动那个不被确定的黑箱吧。」"
  },
  "special_abilities": [
    {
      "name": "因果干涉：绝对不确定性 (Black Box)",
      "description": "御祓泡沫核心的因果操纵能力。他能够通过干涉事件的发生概率来重写既定结果。只要一件事发生的概率不是绝对的0%，他就能强制将其实现。这通常表现为让对手的攻击彻底偏移、将自身的致命伤转变为未发生状态，或者制造出不合常理的奇迹。"
    },
    {
      "name": "结果篡改",
      "description": "固有灵技。直接干涉已经确定的物理现象结果。他曾通过此招瞬间治愈黑铁一辉的重创，方法是将“受伤”这一因果片段强行抹除并替换为“未受伤”的时间线结果。"
    },
    {
      "name": "无法观测 (Fifty-Fifty)",
      "description": "由于他能不断改写自己的因果状态，任何常规的战斗数据、未来预读或感官锁定都无法在他身上保持恒定。这使得他在防御层面上拥有极高的级别（防御力A），即便是顶尖强者也难以捕捉他的真实动向。"
    }
  ],
  "relationships": {
    "东堂刀华": {
      "nature": "拯救者、最亲密的青梅竹马、效忠对象",
      "description": "两人同为育幼院出身。刀华通过温柔的力量感化了曾经暴力的泡沫。泡沫对他人的善意大多源于对刀华的报恩，他是刀华在学生会中最信赖的副手。"
    },
    "黑铁一辉": {
      "nature": "认可的学弟、曾经的切磋对象",
      "description": "泡沫非常欣赏一辉这种能够创造奇迹的类型。在一辉遭遇危机时，曾多次利用Black Box为其疗伤或提供关键信息。"
    },
    "贵德原彼方": {
      "nature": "学生会同僚、老朋友",
      "description": "作为学生会的创始成员，两人共事已久，彼方非常清楚泡沫乐天外表下隐藏的实力。 "
    },
    "紫乃宫天音": {
      "nature": "天敌、恐惧的对象",
      "description": "天音拥有能让所有“愿望”实现的能力，在某种程度上完全克制了泡沫的概率干涉。他在晓学园袭击事件中被天音彻底击败并陷入昏迷。"
    }
  }
}

