    },
    {
      "name": "蹄迹王道 (Circus Maximus)",
      "description": "固有灵绝技。奎多兰最强最快的攻击。约翰跨上灵马并人马合一，将前方存在的所有障碍概念性地“铺平”或“碾碎”为道路，发动无可阻挡的冲锋，具有毁天灭地的动能。"
    },
    {
      "name": "灵装切换：幻想形态",
      "description": "一种基于坚强意志的高端技巧。通过将实物化的灵装强行转回灵魂（幻想）形态，以此来截断欧尔·格尔通过钢丝连接在物理灵装上的强制控制。"
    },
    {
      "name": "固有灵装：黄金战车 (Chariot)",
      "description": "双重形态灵装。平时表现为一柄装饰华丽、蕴含圣力的黄金骑兵枪（Spear）；真实形态（True Form）则是通体闪耀金光的黄金战马，拥有极高的奔跑速度与空中漫步能力。"
    },
    {
      "name": "王室长枪术",
      "description": "约翰精通奎多兰正统的长枪术，配合黄金战马的冲锋，能够产生巨大的破甲与冲击效果。"
    }
  ],
  "relationships": {
    "露娜艾丝·法米利昂": {
      "nature": "青梅竹马、唯一的新娘、灵魂的救赎者",
      "description": "两人相差一岁，情感极其深厚。露娜艾丝对约翰而言不仅是恋人，更是人生的导师。在约翰遭遇非人折磨与操控时，是露娜艾丝的爱唤回了他的理智。约翰愿意为其舍弃生命，甚至不惜自残以阻止身体伤害她。"
    },
    "史黛菈·法米利昂": {
