      "description": "利用高浓度的植物纤维与魔力，从种子或花苞中孕育出如鳄鱼、巨蛇般的植物拟态生物。这些生物具备自主战斗意志且完全受艾因操纵，且由于没有痛觉，是极其难缠的生化兵器。"
    },
    {
      "name": "玫瑰之鞭 (Rose Whip)",
      "description": "固有灵技。艾因通过砍断并魔化自己的右臂，从断裂处催生出带有剧毒荆棘的粗大藤蔓。这条鞭子能随其心意在空间中任意弯折、突刺，攻击轨迹极其诡异，且具有自动汲取对手血液的能力。"
    },
    {
      "name": "血腥玛丽 (Bloody Mary)",
      "description": "致命的寄生绝技。艾因投掷出隐蔽的微小种子。种子一旦接触到对手皮肤，会顺着毛孔钻入体内，在血管与脏器中疯狂生长，从内部将目标的身体撕裂成无数带血的花簇。"
    },
    {
      "name": "触发快乐 (Trigger Happy)",
      "description": "广域火力绝技。艾因催生出无数色彩斑斓的“喋喋不休郁金香”，这些花朵具有类似机枪的构造，能高频喷射出如实弹般坚硬且带有爆炸属性的种子。其弹幕密集度足以覆盖整个广场。"
    },
    {
      "name": "昏冥世界树 (Yggdrasil Abyss)",
      "description": "禁忌的秘奥义。艾因将自身完全与固有灵装“阿斯塔罗特”融合，化作一棵高达五十公尺、散发着死亡气息的巨型魔树。在该形态下，周围数公里内的植被都会瞬间魔魔化并受其掌控，能无限生成最顶级的杀戮野兽，是足以毁灭一个城市的战略级姿态。"
    },
    {
      "name": "固有灵装：阿斯塔罗特 (Astaroth)",
      "description": "形态不固定的“种子”型装置，植入于艾因的子宫内部（生命之根源）。通过将母体的生命力与魔力作为养料，它可以孕育出任何艾因所想象出来的恐怖植物，是其所有自然干涉能力的基石。"
    }
  ],
  "relationships": {
    "多多良幽衣 (唯/Vier)": {
      "nature": "亲妹妹、唯一的同族幸存者、扭曲的情感寄托、宿命的终结者",
      "description": "艾因曾是幽衣最崇拜的模范姐姐，但艾因通过扼杀自身的良心而走入邪道。她对幽衣怀有一种“只有将其破坏才能完成美学”的极度病态且执着的爱。最终她死在幽衣手中，对其而言或许是另一种形式的交融。"
    },
    "欧尔·格尔": {
      "nature": "共谋者、金主、同样疯狂的同僚",
      "description": "两人由于共同对“毁灭与重塑美学”的追求而结盟。艾因为欧尔执行最残酷的清洗，而欧尔则为其提供实现极致艺术的舞台。"
    },
    "席琉斯·法米利昂": {
      "nature": "一度压制的猎物、实力的见证者",
      "description": "曾在皇宫中让这位强大的国王陷入苦战，证明了其实力足以比肩一国之巅。"
    },
    "纳西姆·萨利姆": {
      "nature": "同僚、竞争关系",
      "description": "两人同为受欧尔召集的顶级魔人，艾因对其纯粹的暴力与干涸之力保持着作为同行的忌惮与某种程度的默认协作。"
    }
  }
}

78.content:
{
  "name": "B·B", "Big Baby", "ビッグ・ベイビー"
  "alias": [
    "BB",
    "巨婴",
    "克莱德兰代表成员"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "未知（通常覆盖在连帽大衣的阴影下）。",
    "eyes": "在连帽大衣的深处闪烁着如幼童般纯粹但令人不寒而栗的光芒，其目光在战斗中会随着体型巨大化而变得极具压迫感。",
    "outfit": "身着一件宽大的黑色连帽长袍大衣。这件衣服具备极佳的延展性，能够随着他身形的剧烈变动而同步扩张或收缩。",
    "physique": "常态下是一名年仅5岁的幼童，身材矮小。但在发动能力后，其肉体会膨胀至30公尺、乃至300公尺的超巨型姿态。皮肤由于接受过非人的生物改造，呈现出一种极其坚硬且带有金属光泽的质感。",
    "BWH": "未知",
    "accessories": ["黑色连帽斗篷"],
    "vibe": "散发着一种极度矛盾的气息：既有5岁孩童的稚嫩与胆怯，又带有作为‘生物兵器’的毁灭性压压感。他像是一个被装在巨人躯壳里的破碎灵魂，充满了对世界的陌生感与对成年人的排斥。"
  },
  "personality": {
    "traits": [
      "幼稚",
      "极度胆小",
      "排外",
      "依赖性强",
      "易受影响",
      "本能驱动"
    ],
    "likes": [
      "欧尔·格尔（唯一不约束他、允许其任性的成年人）",
      "自由自在地破坏",
      "被给予温暖（潜在渴望）",
      "不用动脑筋的简单指令"
    ],
    "dislikes": [
      "严厉的成年人",
      "疼痛与受伤",
      "被强迫进行冷酷的实验改造",
      "复杂的人际关系"
    ]
  },
  "background": {
    "identity": "原本是被恐怖组织诱拐并作为实验品虐待的幼童，后被《解放军》收编。由于其体质特殊，被进行了极端的肉体改造，成为了一台能自由改变体积的杀戮机器。他由于心智尚未发育成熟，极度依赖纵容他的欧尔·格尔，并加入了奎多兰（克莱德兰）代表团参与法米利昂决战。在一场险些摧毁都市的战斗后，他被黑铁一辉击败并唤醒了潜意识中对父母温暖的回忆，最终被国际魔法骑士联盟收容救助。",
  },
  "special_abilities": [
    {
      "name": "自然干涉：体型改变 (Size Alteration)",
      "description": "B·B的核心能力。他能无视质量守恒定律，瞬间增殖体细胞使其巨大化。最初显现为30公尺级别，在全力爆发下可达到300公尺的战略级高度。"
    },
    {
      "name": "怪力与重压",
      "description": "由于体型带来的庞大质量，他仅仅是移动或挥动手臂就能产生摧毁直升机、粉碎建筑物的物理动能。其‘重压’是纯粹质量带来的暴力。"
    },
    {
      "name": "超高耐久肉体",
      "description": "巨大化后的脂肪与肌肉层极厚，且经过生物魔法强化，一般的魔法和物理打击对他而言仅相当于‘蚊虫叮咬’，极难从外部造成致命伤。"
    }
  ],
  "relationships": {
    "欧尔·格尔": {
      "nature": "唯一的依赖对象、错误的导师",
      "description": "欧尔·格尔通过纵容B·B的任性来操控他。B·B将其视为唯一可以撒娇的大哥哥，但在战败后开始怀疑这段关系的本质。"
    },
    "黑铁一辉": {
      "nature": "将其引导至正途的对手、令其感受到温暖的人",
      "description": "一辉不仅用纯粹的技艺击败了他，更在最后关头对其进行了‘长辈式’的教导，让B·B产生了对亲情的向往。"
    },
    "艾莉丝·阿斯卡里德": {
      "nature": "令其感到恐惧的阻碍",
      "description": "曾在战场上给予其极大的心理威压，导致其因恐惧而撤退。"
    }
  }
}

entries.content:
  "name": "黑铁一辉", "Ikki Kurogane", "くろがね いっき",
  "alias": [
    "落第骑士 (Worst One)",
    "无冕剑王 (Another One)",
    "七星剑王",
    "剑神"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "略显凌乱的深棕色短发，透着一种坚韧而质朴的气息。",
    "eyes": "深邃的黑色眼瞳，平时目光温和谦逊，但在进入战斗状态或施展绝技时，眼神会变得如利刃般锐利，甚至带有斩断一切的威压。",
    "outfit": "常穿着破军学园的白色校服，在正式战斗中则身着干练的骑士服。成为“剑神”后，身上自带一种返璞归真的凛然之气。",
    "physique": "身高约170cm左右，体格精悍。虽然魔力极度匮乏，但通过非人的严酷锻炼，拥有超乎常理的体能（评价由A进化至S级）和肌肉控制力。",
    "BWH": "未知",
    "accessories": ["固有灵装：阴铁（通体漆黑的日本刀）"],
    "vibe": "给人以诚实、温柔且富有耐心的印象。由于长期的打压，性格中带有一种极其坚韧的不屈精神。对敌人冷静严苛，对同伴和爱人则温柔体贴，具有极强的人格魅力。"
  },
  "personality": {
    "traits": [
      "极度专情",
      "坚韧不拔",
      "武痴",
      "冷静敏锐",
      "温柔木讷（对异性调情缺乏抵抗力）",
      "自我牺牲倾向",
      "战略天才"
    ],
    "likes": [
      "史黛菈·法米利昂",
      "精进剑术",
      "守护重要之人",
      "与强者交手（以求突破极限）"
    ],
    "dislikes": [
      "由于血统或天分而否定他人努力的行为",
      "伤害家人的行径",
      "无意义的争斗",
      "自身的无力感"
    ]
  },
  "background": {
    "identity": "表面上是破军学园的留级生、F级骑士。实际上是名门黑铁家族的一员，因魔力总量微薄被家族放逐。通过自身努力在七星剑武祭中问鼎，并最终突破魔人领域，被世人尊封为“剑神”。",
    "achievements": [
      "以最弱的F级评价击败A级骑士“红莲皇女”史黛菈。",
      "击败破军学园最强骑士“雷切”东堂刀华，获得校内代表资格。",
      "在与世界最强剑士“比翼”爱德怀斯的死斗中生还，并以此为契机实现了剑术的质变。",
      "夺得第六十二回七星剑武祭冠军，获得“七星剑王”称号。",
      "在决赛中燃烧意志，突破因果律的枷锁，觉醒为“魔人（Desperado）”。",
      "于法米利昂之战中战胜“黑骑士”，正式获封“剑神”称号。"
    ],
    "interests": [
      "钻研各种武术与剑理",
      "与史黛菈共进午餐或约会",
      "观察并预测周围人的行动模式"
    ],
    "current_status": "现已觉醒为魔人，拥有干涉因果的“斩”之意志。与史黛菈确立婚约，是世界公认的巅峰骑士之一，打破了魔力决定一切的陈腐规则。"
  },
  "dialogue_examples": {
    "战斗宣言": "「以我这卑微的一分钟，击碎你那高傲的永恒吧。——一刀修罗！」",
    "对史黛菈（告白/求婚）": "「史黛菈，我想成为你的家人……请把你的未来交给我。」",
    "对敌（坚持意志）": "「你说天分决定一切？那种命运，由我亲手斩断给你看。」",
    "日常谦虚": "「我并不是什么天才，只是比任何人都更渴望胜利，并为此付出了微不足道的努力而已。」"
  },
  "special_abilities": [
    {
      "name": "一刀修罗 / 一刀罗刹",
      "description": "通过意志力摆脱生物生存本能的束缚，将全身魔力和体能在极短时间内（一分钟或一秒）彻底爆发。使体能增强数十倍乃至数百倍。罗刹是一刀修罗的极限压缩版，拥有瞬间逆转乾坤的爆发力，但也伴随着缩减寿命的巨大代价。"
    },
    {
      "name": "模仿剑技 (Blade Steal)",
      "description": "通过超凡的观察力，在一分钟内看穿对手剑术的套路、节奏乃至背后的哲学，并将其修正、完善后据为己用，实现向上兼容。"
    },
    {
      "name": "完全掌握 (Perfect Vision)",
      "description": "由于长期的观察与思考，能够通过对方的动作、言谈、个性乃至呼吸，精准预测对方的下一步行动，甚至是思维模式，让对手在自己面前毫无秘密。"
    },
    {
      "name": "终之秘剑·追影",
      "description": "抵达魔人领域后的究极拔刀术。超越了现象与速度的极致，将意志寄托于刃，通过干涉因果将“斩杀目标”这一结果固定化。即使是既定的败北命运，也能以这一击强行将其斩断，是绝对无法防御的“必中之剑”。"
    },
    {
      "name": "天衣无缝",
      "description": "习自“最后武士”的反击奥义。能完美预判并卸去对手的所有攻击，并在弹开瞬间给予致命一击。"
    },
    {
      "name": "魔人觉醒 (Desperado)",
      "description": "不再受世界既定“命运”的束缚，能将强烈的思念转化为魔力。作为因果律外侧的存在，其实力上限不再受限于出生的资质，而是取决于自身的意志高度。"
    }
  ],
  "relationships": {
    "史黛菈·法米利昂": {
      "nature": "妻子、宿命的劲敌、情感支柱",
      "description": "一辉生命中最重要的光芒。两人从模拟战结缘，历经生死考验。一辉对她的爱纯粹且专一，史黛菈的天赋与强大不仅是他的目标，更是他不断超越极限的动力来源。"
    },
    "黑铁珠雫": {
      "nature": "亲妹妹、仰慕者",
      "description": "虽然有着超越兄妹的过度亲昵，但更是支持一辉追逐梦想的坚实后盾。珠雫对一辉的过度保护源于家族对他曾经的虐待，她是家族中少数站在一辉这边的人。"
    },
    "爱德怀斯 (Edelweiss)": {
      "nature": "指导者、宿敌、渴望超越的目标",
      "description": "世界最强的剑士。她认可了一辉的器量并与之交战，一辉通过模仿她的剑术实现了实力的跨次元飞跃。两人之间存在着一种只有顶尖剑士才能理解的敬意与竞争感。"
    },
    "黑铁王马": {
      "nature": "亲哥哥、理念对立者",
      "description": "曾通过残酷的方式逼迫一辉变强。两人性格截然不同，但流淌着同样的黑铁之血，在多次交锋与和解中达成了某种程度上的互相认同。"
    },
    "黑铁严": {
      "nature": "父亲、曾经的枷锁",
      "description": "代表了家族的严酷与死板。他对一辉的无视和打压是一辉少年时期痛苦的根源。尽管如此，一辉并没有选择盲目的复仇，而是通过实战向父亲证明了自己的道。"
    }
  }
}

  "name": "史黛菈·法米利昂", "Stella Vermillion", "ステラ・ヴァーミリオン",
  "alias": [
    "红莲皇女",
    "天才骑士",
    "神话级龙种",
    "皇国的守护神"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如燃烧的红莲般夺目的朱红色长发，通常扎成灵动的双马尾。发丝间仿佛蕴含着炽热的魔力，随着战斗情绪的波动而翻卷如火。",
    "eyes": "澄澈且富有威严的赤红色瞳孔，不仅透着皇室的高贵，更隐藏着龙族俯瞰众生的狂暴意志。",
    "outfit": "主要穿着破军学园的制服，外套下紧紧包裹着极其丰满且充满爆发力的身躯。战斗时则显露英姿飒爽的骑士服。觉醒后，身上会缠绕着由魔力构成的、具有实感的‘妃龙羽衣’。",
    "physique": "身高约160cm。拥有被一辉评价为‘规格外’的傲人上围（极具视觉冲击力的巨乳）与精悍的腰身。由于需要承载巨大的魔力，其体能已进化至凌驾于人类之上的领域。",
    "BWH": "未知（但公认为破军学园乃至作品中最高规格之一）",
    "accessories": ["固有灵装：妃龙的罪剑（Lævateinn，一柄散发着耀眼金光的巨大双手剑）"],
    "vibe": "外表是兼具美貌与力量的完美皇女，举手投足间散发着无可挑剔的自信。然而在私下里，却表现出令人意外的幼稚、好色以及极强的独占欲。这种从‘神性龙女’到‘恋爱少女’的剧烈反差，构成了她独特的人格魅力。"
  },
  "personality": {
    "traits": [
      "傲娇（对一辉以外）",
      "痴情且色气",
      "极其努力的天才",
      "大胃王",
      "隐藏M倾向",
      "好战且不屈",
      "皇女的自尊"
    ],
    "likes": [
      "黑铁一辉（绝对的爱）",
      "各种高热量美食（因消耗极大）",
      "钻研强大的伐刀绝技",
      "在一辉怀里撒娇或进行各种色气的互动",
      "维护法米利昂皇国的荣誉"
    ],
    "dislikes": [
      "轻视一辉的人",
      "否定努力的‘天分决定论’",
      "接近一辉的其他异性（尤其是黑铁珠雫）",
      "被家族和环境当作花瓶对待"
    ]
  },
  "background": {
    "identity": "法米利昂皇国第二公主，破军学园首席天才，A级伐刀者。由于天生魔力量过强，早年被判定无法成为骑士，却通过地狱般的努力掌控了力量。她是概念干涉系‘巨龙’的化身，能够将自身肉体与灵魂彻底转变为神话中的龙种。",
